#!/usr/bin/env node
/**
 * Tests for the lite path of workflows/dev-loop.js (args.targeted): at S and M the block, fix and lane gates run
 * `--targeted`, one full gate (label "full gate...", a code-reviewer on haiku) runs before the final readers and again
 * after a fix round that changed code, a red full gate gets one fix and one regate before STALL gate-red, an
 * unparsable line is verify-not-run, and a run without `targeted` stays as it was (size L: dev-loop-lite-large.test.mjs). The shared harness is
 * tools/dev-loop.harness.mjs (it answers the full gate calls).
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run, ARGS, ARGS_M, review, finding, impl, gate, tasksOf, verifyGate, isReview, PASS, FAIL } from './dev-loop.harness.mjs';

const VERIFY = 'node --test x';
const TEMPLATE = 'node --test {files}';
const LITE = { ...ARGS, verify: VERIFY, targeted: TEMPLATE, start: { head: 'abc1234', dirty: ['notes/todo.md'] } };
const LITE_M = { ...ARGS_M, verify: VERIFY, targeted: TEMPLATE, start: { head: 'abc1234', dirty: ['notes/todo.md'] }, plan: { tasks: tasksOf(2) } };
const green = () => impl({ gate: gate() });
const fullGates = (calls) => calls.filter((c) => /^full gate/.test(c.opts.label ?? '') && c.opts.agentType !== 'implementer');
const implementers = (calls) => calls.filter((c) => c.opts.agentType === 'implementer');
const gateCommand = (prompt) => prompt.split('\n').find((l) => /gate\.mjs --root [^\n]* --test /.test(l) && !/--wait/.test(l)) ?? '';
const clause = (command, re) => command.match(re)?.[0];
// a full-gate scripted from a queue of last lines, the last one repeating
const fullQueue = (...lines) => ({ fullGate: () => ({ gate: lines.length > 1 ? lines.shift() : lines[0] }) });

test('given S with targeted, when the loop runs, then the block gate line has --targeted and the full gate has none and the same --dirty, head and test as the after-OK gate', async () => {
  // Given
  const impls = [green()];

  // When
  const { out, calls } = await run(LITE, [review([])], impls);

  // Then
  const block = calls.find((c) => c.opts.agentType === 'implementer').prompt;
  assert.match(block, /--targeted 'node --test \{files\}'/);
  const fulls = fullGates(calls);
  assert.equal(fulls.length, 1);
  assert.equal(fulls[0].opts.agentType, 'code-reviewer');
  assert.equal(fulls[0].opts.model, 'haiku');
  const command = gateCommand(fulls[0].prompt);
  assert.match(command, /gate\.mjs --root 'C:\/repo' --head abc1234 --test 'node --test x'/);
  assert.doesNotMatch(command, /--targeted|--no-scope|--force/);
  assert.match(command, /--dirty '[^']*todo\.md[^']*'/);
  assert.equal(clause(command, /--dirty '[^']*'/), clause(gateCommand(block), /--dirty '[^']*'/));
  assert.match(fulls[0].prompt, /--wait/);
  assert.equal(out.status, 'OK');
});

test('given S with targeted, when the loop runs, then the full gate runs after the implementer and before every final reader', async () => {
  // Given / When
  const { calls } = await run(LITE, [review([])], [green()]);

  // Then
  const at = (pred) => calls.findIndex(pred);
  const full = at((c) => /^full gate/.test(c.opts.label ?? ''));
  assert.ok(full > at((c) => c.opts.agentType === 'implementer'));
  assert.ok(full < at((c) => isReview(c.opts.label)));
});

test('given M with targeted, when the loop runs, then the block gate has --targeted and one full gate without it runs before the readers', async () => {
  // Given / When
  const { out, calls } = await run(LITE_M, [review([])], [green()]);

  // Then
  assert.match(calls.find((c) => c.opts.agentType === 'implementer').prompt, /--targeted 'node --test \{files\}'/);
  const fulls = fullGates(calls);
  assert.equal(fulls.length, 1);
  assert.doesNotMatch(gateCommand(fulls[0].prompt), /--targeted/);
  assert.equal(out.status, 'OK');
});

test('given a red full gate, when the loop runs, then one implementer fix and one full regate follow and the run stalls gate-red before any reader', async () => {
  // Given
  const red = gate('red', { test: 'suite broke in lib' });

  // When
  const { out, calls } = await run(LITE, [review([])], [green(), green()], fullQueue(red));

  // Then
  assert.equal(out.status, 'STALL');
  assert.equal(out.stall.why, 'gate-red');
  assert.equal(fullGates(calls).length, 2);
  assert.equal(implementers(calls).length, 2);
  assert.match(implementers(calls)[1].prompt, /suite broke in lib/);
  assert.equal(calls.filter((c) => isReview(c.opts.label)).length, 0);
});

test('given a red full gate that the fix turns green, when the loop runs, then the readers run and the run ends OK', async () => {
  // Given
  const queue = fullQueue(gate('red', { test: 'suite broke in lib' }), gate());

  // When
  const { out, calls } = await run(LITE, [review([])], [green(), green()], queue);

  // Then
  assert.equal(out.status, 'OK');
  assert.equal(fullGates(calls).length, 2);
  assert.equal(implementers(calls).length, 2);
});

test('given a fix round that changed code after the full gate, when the loop runs, then the full gate runs again after the fix and before OK', async () => {
  // Given
  const reviews = [review([], [finding()]), review([{ id: 'F1', status: 'closed' }])];
  const fixed = impl({ gate: gate(), snapshot: { tree: 't2', files: ['src/Orders/OrdersQuery.cs'], churn: 3 } });

  // When
  const { out, calls } = await run(LITE, reviews, [green(), fixed]);

  // Then
  assert.equal(out.status, 'OK');
  const fix = calls.findIndex((c) => c.opts.label === 'fix round 1 findings');
  assert.match(calls[fix].prompt, /--targeted 'node --test \{files\}'/);
  const fulls = calls.map((c, i) => [c, i]).filter(([c]) => /^full gate/.test(c.opts.label ?? '') && c.opts.agentType !== 'implementer');
  assert.equal(fulls.length, 2);
  assert.ok(fulls[1][1] > fix);
});

test('given a full gate line that does not parse, when the loop runs, then the run stalls verify-not-run and never reaches OK', async () => {
  // Given
  const queue = { fullGate: () => ({ gate: 'all tests passed, I think' }) };

  // When
  const { out } = await run(LITE, [review([])], [green(), green()], queue);

  // Then
  assert.equal(out.status, 'STALL');
  assert.equal(out.stall.why, 'verify-not-run');
});

test('given the verify went from targeted pass to full fail, when verifyGate reads it, then there is no green-to-red stall but a V finding', () => {
  // Given
  const report = { verify: FAIL };

  // When
  const changed = verifyGate({ report, verifyCmd: 'x', previous: 'pass', previousMode: 'targeted', mode: 'full' });
  const same = verifyGate({ report, verifyCmd: 'x', previous: 'pass', previousMode: 'full', mode: 'full' });

  // Then
  assert.equal(changed.stall, undefined);
  assert.equal(changed.finding.id, 'V1');
  assert.equal(same.stall.why, 'green-to-red');
});

test('given no targeted arg, when the loop runs, then no gate line has --targeted and no full gate call is made', async () => {
  // Given
  const args = { ...ARGS, verify: VERIFY };

  // When
  const { out, calls } = await run(args, [review([])], [green()]);

  // Then
  assert.equal(out.status, 'OK');
  assert.equal(fullGates(calls).length, 0);
  assert.equal(calls.filter((c) => /--targeted/.test(c.prompt)).length, 0);
});

test('given a passing verify report, when verifyGate reads it without modes, then it still passes', () => {
  // Given / When
  const g = verifyGate({ report: { verify: PASS }, verifyCmd: 'x' });

  // Then
  assert.deepEqual(g, { status: 'pass' });
});
